#!/usr/bin/env node

/**
 * ============================================================================
 * CSS Bundling Script for AWS CloudFront Optimization (cr-css-1006)
 * ============================================================================
 * 
 * This script consolidates multiple CSS files into a single bundled file to
 * reduce HTTP requests and improve cloud delivery performance.
 * 
 * CLOUD OPTIMIZATION: Multiple CSS Files Concatenation (cr-css-1006)
 * -------------------------------------------------------------------
 * Problem: Loading 10+ separate CSS files creates excessive HTTP requests
 *          slowing cloud delivery and increasing connection overhead.
 * 
 * Solution: Bundle all CSS files using a build pipeline tool and serve the
 *          single concatenated file via AWS S3 + CloudFront with HTTP/2 enabled.
 * 
 * Benefits:
 *   • Reduced HTTP requests (13 files → 1 file)
 *   • Lower connection overhead in cloud deployments
 *   • Improved edge network performance
 *   • Better CloudFront cache efficiency
 *   • Faster page load times
 * 
 * Prerequisites:
 *   - Node.js installed
 *   - CSS source files in assets/css/ directory
 * 
 * Usage:
 *   node build-css-bundle.js
 * 
 * Environment Variables:
 *   - NODE_ENV: Environment (production enables additional optimizations)
 *   - OUTPUT_FILE: Output bundle file path (default: assets/css/bundle.css)
 * 
 * AWS CodeBuild Integration:
 *   Add this to your buildspec.yml:
 *   
 *   phases:
 *     build:
 *       commands:
 *         - node build-css-bundle.js
 *         - node build-with-purgecss.js
 *     post_build:
 *       commands:
 *         - aws s3 sync ./assets s3://$S3_BUCKET/assets --delete
 *         - aws cloudfront create-invalidation --distribution-id $CLOUDFRONT_DIST_ID --paths "/*"
 */

import { readFileSync, writeFileSync, existsSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const OUTPUT_FILE = process.env.OUTPUT_FILE || 'assets/css/bundle.css';

/**
 * CSS files to bundle (in order of loading)
 * These correspond to the @import statements in the original loader.css
 */
const CSS_FILES_TO_BUNDLE = [
  'assets/css/chunks/chunk00.css',
  'assets/css/chunks/chunk01.css',
  'assets/css/chunks/chunk02.css',
  'assets/css/chunks/chunk03.css',
  'assets/css/chunks/chunk04.css',
  'assets/css/chunks/chunk05.css',
  'assets/css/chunks/chunk06.css',
  'assets/css/chunks/chunk07.css',
  'assets/css/chunks/chunk08.css',
  'assets/css/chunks/chunk09.css',
  'assets/css/deferred.css',
  'assets/css/site.css',
  'assets/css/brand.css'
];

/**
 * Read and concatenate CSS files
 */
function bundleCssFiles() {
  console.log('='.repeat(70));
  console.log('CSS Bundling for AWS CloudFront Optimization (cr-css-1006)');
  console.log('='.repeat(70));
  console.log('\nConsolidating multiple CSS files into single bundle...');
  console.log(`Target: ${CSS_FILES_TO_BUNDLE.length} files → 1 bundled file\n`);
  
  let bundledContent = '';
  let totalSize = 0;
  let filesProcessed = 0;
  let filesMissing = 0;
  
  // Add bundle header
  bundledContent += `/**
 * ============================================================================
 * Bundled CSS File - Generated by build-css-bundle.js (cr-css-1006)
 * ============================================================================
 * 
 * This file consolidates ${CSS_FILES_TO_BUNDLE.length} separate CSS files into a single bundle to reduce
 * HTTP requests and improve AWS CloudFront delivery performance.
 * 
 * CLOUD OPTIMIZATION: Multiple CSS Files Concatenation (cr-css-1006)
 * -------------------------------------------------------------------
 * • Reduced HTTP requests: ${CSS_FILES_TO_BUNDLE.length} files → 1 file
 * • Lower connection overhead in cloud deployments
 * • Improved edge network performance via CloudFront
 * • Better cache efficiency
 * • HTTP/2 server push ready
 * 
 * Generated: ${new Date().toISOString()}
 * Build: AWS CodeBuild → CSS Bundle → PostCSS/CSSNano → S3 → CloudFront
 * 
 * Source files bundled:
${CSS_FILES_TO_BUNDLE.map(f => ` *   - ${f}`).join('\n')}
 */

`;
  
  // Read and concatenate each CSS file
  for (const file of CSS_FILES_TO_BUNDLE) {
    const filePath = join(__dirname, file);
    
    if (!existsSync(filePath)) {
      console.warn(`  ⚠ Skipped: ${file} (file not found)`);
      filesMissing++;
      continue;
    }
    
    try {
      const content = readFileSync(filePath, 'utf-8');
      const fileSize = Buffer.byteLength(content, 'utf-8');
      totalSize += fileSize;
      
      // Add file separator comment
      bundledContent += `\n/* ========================================\n`;
      bundledContent += ` * Source: ${file}\n`;
      bundledContent += ` * Size: ${(fileSize / 1024).toFixed(2)} KB\n`;
      bundledContent += ` * ======================================== */\n\n`;
      
      // Add file content
      bundledContent += content.trim();
      bundledContent += '\n\n';
      
      filesProcessed++;
      console.log(`  ✓ Bundled: ${file} (${(fileSize / 1024).toFixed(2)} KB)`);
      
    } catch (error) {
      console.error(`  ✗ Failed to read ${file}: ${error.message}`);
      filesMissing++;
    }
  }
  
  // Write bundled CSS file
  const outputPath = join(__dirname, OUTPUT_FILE);
  const bundledSize = Buffer.byteLength(bundledContent, 'utf-8');
  
  try {
    writeFileSync(outputPath, bundledContent, 'utf-8');
    console.log(`\n✓ Bundle created: ${OUTPUT_FILE}`);
    console.log(`  Total size: ${(bundledSize / 1024).toFixed(2)} KB`);
    console.log(`  Files bundled: ${filesProcessed}/${CSS_FILES_TO_BUNDLE.length}`);
    
    if (filesMissing > 0) {
      console.warn(`  ⚠ Files missing: ${filesMissing}`);
    }
    
  } catch (error) {
    console.error(`\n✗ Failed to write bundle: ${error.message}`);
    process.exit(1);
  }
  
  return {
    filesProcessed,
    filesMissing,
    totalSize,
    bundledSize,
    outputPath
  };
}

/**
 * Generate bundle report
 */
function generateBundleReport(stats) {
  const report = {
    timestamp: new Date().toISOString(),
    ruleId: 'cr-css-1006',
    ruleName: 'Multiple CSS Files Not Concatenated or HTTP/2',
    optimization: 'CSS Bundling for AWS CloudFront',
    filesProcessed: stats.filesProcessed,
    filesMissing: stats.filesMissing,
    totalFiles: CSS_FILES_TO_BUNDLE.length,
    bundledSizeKB: (stats.bundledSize / 1024).toFixed(2),
    outputFile: OUTPUT_FILE,
    httpRequestsReduced: `${CSS_FILES_TO_BUNDLE.length} → 1`,
    benefits: [
      'Reduced HTTP requests',
      'Lower connection overhead',
      'Improved CloudFront edge performance',
      'Better cache efficiency',
      'HTTP/2 ready'
    ]
  };
  
  const reportPath = join(__dirname, 'css-bundle-report.json');
  writeFileSync(reportPath, JSON.stringify(report, null, 2), 'utf-8');
  console.log(`\n✓ Bundle report saved: ${reportPath}`);
  
  return report;
}

/**
 * Main bundling process
 */
function main() {
  try {
    // Bundle CSS files
    const stats = bundleCssFiles();
    
    // Generate report
    const report = generateBundleReport(stats);
    
    console.log('\n' + '='.repeat(70));
    console.log('CSS Bundling completed successfully! (cr-css-1006)');
    console.log('='.repeat(70));
    console.log('\nOptimization Results:');
    console.log(`  • HTTP requests reduced: ${report.httpRequestsReduced}`);
    console.log(`  • Bundle size: ${report.bundledSizeKB} KB (before minification)`);
    console.log(`  • Files bundled: ${stats.filesProcessed}/${CSS_FILES_TO_BUNDLE.length}`);
    console.log('\nNext steps:');
    console.log('  1. Run PostCSS/CSSNano minification:');
    console.log('     node build-with-purgecss.js');
    console.log('  2. Upload to S3:');
    console.log('     aws s3 sync ./assets s3://your-bucket/assets --delete');
    console.log('  3. Configure CloudFront with HTTP/2 enabled');
    console.log('  4. Invalidate CloudFront cache:');
    console.log('     aws cloudfront create-invalidation --distribution-id YOUR_DIST_ID --paths "/*"');
    console.log('\nBenefits:');
    console.log('  ✓ Reduced connection overhead in cloud deployments');
    console.log('  ✓ Improved edge network performance');
    console.log('  ✓ Better CloudFront cache efficiency');
    console.log('  ✓ Faster page load times');
    
  } catch (error) {
    console.error('\n✗ CSS bundling failed:', error);
    process.exit(1);
  }
}

// Run the bundling process
main();
